/**
 * Constructs an instance set to the milliseconds from 1970-01-01T00:00:00Z
 * using <code>ISOChronology</code> in the specified time zone.
 * <p>
 * If the specified time zone is null, the default zone is used.
 *
 * @param instant  the milliseconds from 1970-01-01T00:00:00Z
 * @param zone  the time zone, null means default zone
 */
public DateTime(long instant, DateTimeZone zone) {
    super(instant, zone);
}

/**
 * @return false if error.
 */
static boolean test(String id, DateTimeZone tz) {
    if (!id.equals(tz.getID())) {
        return true;
    }

    // Test to ensure that reported transitions are not duplicated.

    long millis = ISOChronology.getInstanceUTC().year().set(0, 1850);
    long end = ISOChronology.getInstanceUTC().year().set(0, 2050);

    int offset = tz.getOffset(millis);
    String key = tz.getNameKey(millis);

    List<Long> transitions = new ArrayList<Long>();

    while (true) {
        long next = tz.nextTransition(millis);
        if (next == millis || next > end) {
            break;
        }

        millis = next;

        int nextOffset = tz.getOffset(millis);
        String nextKey = tz.getNameKey(millis);

        if (offset == nextOffset
            && key.equals(nextKey)) {
            System.out.println("*d* Error in " + tz.getID() + " "
                               + new DateTime(millis,
                                              ISOChronology.getInstanceUTC()));
            return false;
        }

        if (nextKey == null || (nextKey.length() < 3 && !"??".equals(nextKey))) {
            System.out.println("*s* Error in " + tz.getID() + " "
                               + new DateTime(millis,
                                              ISOChronology.getInstanceUTC())
                               + ", nameKey=" + nextKey);
            return false;
        }

        transitions.add(Long.valueOf(millis));

        offset = nextOffset;
        key = nextKey;
    }

    // Now verify that reverse transitions match up.

    millis = ISOChronology.getInstanceUTC().year().set(0, 2050);
    end = ISOChronology.getInstanceUTC().year().set(0, 1850);

    for (int i=transitions.size(); --i>= 0; ) {
        long prev = tz.previousTransition(millis);
        if (prev == millis || prev < end) {
            break;
        }

        millis = prev;

        long trans = transitions.get(i).longValue();

        if (trans - 1 != millis) {
            System.out.println("*r* Error in " + tz.getID() + " "
                               + new DateTime(millis,
                                              ISOChronology.getInstanceUTC()) + " != "
                               + new DateTime(trans - 1,
                                              ISOChronology.getInstanceUTC()));

            return false;
        }
    }

    return true;
}

private static void printUsage() {
    System.out.println("Usage: java org.joda.time.tz.ZoneInfoCompiler <options> <source files>");
    System.out.println("where possible options include:");
    System.out.println("  -src <directory>    Specify where to read source files");
    System.out.println("  -dst <directory>    Specify where to write generated files");
    System.out.println("  -verbose            Output verbosely (default false)");
}

/**
 * Returns a map of ids to DateTimeZones.
 *
 * @param outputDir optional directory to write compiled data files to
 * @param sources optional list of source files to parse
 */
public Map<String, DateTimeZone> compile(File outputDir, File[] sources) throws IOException {
    if (sources != null) {
        for (int i=0; i<sources.length; i++) {
            BufferedReader in = new BufferedReader(new FileReader(sources[i]));
            parseDataFile(in);
            in.close();
        }
    }

    if (outputDir != null) {
        if (!outputDir.exists()) {
            throw new IOException("Destination directory doesn't exist: " + outputDir);
        }
        if (!outputDir.isDirectory()) {
            throw new IOException("Destination is not a directory: " + outputDir);
        }
    }

    Map<String, DateTimeZone> map = new TreeMap<String, DateTimeZone>();

    System.out.println("Writing zoneinfo files");
    for (int i=0; i<iZones.size(); i++) {
        Zone zone = iZones.get(i);
        DateTimeZoneBuilder builder = new DateTimeZoneBuilder();
        zone.addToBuilder(builder, iRuleSets);
        final DateTimeZone original = builder.toDateTimeZone(zone.iName, true);
        DateTimeZone tz = original;
        if (test(tz.getID(), tz)) {
            map.put(tz.getID(), tz);
            if (outputDir != null) {
                if (ZoneInfoCompiler.verbose()) {
                    System.out.println("Writing " + tz.getID());
                }
                File file = new File(outputDir, tz.getID());
                if (!file.getParentFile().exists()) {
                    file.getParentFile().mkdirs();
                }
                OutputStream out = new FileOutputStream(file);
                builder.writeTo(zone.iName, out);
                out.close();

                // Test if it can be read back.
                InputStream in = new FileInputStream(file);
                DateTimeZone tz2 = DateTimeZoneBuilder.readFrom(in, tz.getID());
                in.close();

                if (!original.equals(tz2)) {
                    System.out.println("*e* Error in " + tz.getID() +
                                       ": Didn't read properly from file");
                }
            }
        }
    }

    for (int pass=0; pass<2; pass++) {
        for (int i=0; i<iLinks.size(); i += 2) {
            String id = iLinks.get(i);
            String alias = iLinks.get(i + 1);
            DateTimeZone tz = map.get(id);
            if (tz == null) {
                if (pass > 0) {
                    System.out.println("Cannot find time zone '" + id +
                                       "' to link alias '" + alias + "' to");
                }
            } else {
                map.put(alias, tz);
            }
        }
    }

    if (outputDir != null) {
        System.out.println("Writing ZoneInfoMap");
        File file = new File(outputDir, "ZoneInfoMap");
        if (!file.getParentFile().exists()) {
            file.getParentFile().mkdirs();
        }

        OutputStream out = new FileOutputStream(file);
        DataOutputStream dout = new DataOutputStream(out);
        // Sort and filter out any duplicates that match case.
        Map<String, DateTimeZone> zimap = new TreeMap<String, DateTimeZone>(String.CASE_INSENSITIVE_ORDER);
        zimap.putAll(map);
        writeZoneInfoMap(dout, zimap);
        dout.close();
    }

    return map;
}

/**
 * Constructs an instance set to the milliseconds from 1970-01-01T00:00:00Z
 * using <code>ISOChronology</code> in the specified time zone.
 * <p>
 * If the specified time zone is null, the default zone is used.
 *
 * @param instant  the milliseconds from 1970-01-01T00:00:00Z
 * @param zone  the time zone, null means default zone
 */
public BaseDateTime(long instant, DateTimeZone zone) {
    this(instant, ISOChronology.getInstance(zone));
}

long setYear(long instant, int year) {
    int thisYear = getYear(instant);
    int dayOfYear = getDayOfYear(instant, thisYear);
    int millisOfDay = getMillisOfDay(instant);

    if (dayOfYear > (31 + 28)) { // after Feb 28
        if (isLeapYear(thisYear)) {
            // Current date is Feb 29 or later.
            if (!isLeapYear(year)) {
                // Moving to a non-leap year, Feb 29 does not exist.
                dayOfYear--;
            }
        } else {
            // Current date is Mar 01 or later.
            if (isLeapYear(year)) {
                // Moving to a leap year, account for Feb 29.
                dayOfYear++;
            }
        }
    }

    instant = getYearMonthDayMillis(year, 1, dayOfYear);
    instant += millisOfDay;

    return instant;
}

/**
 * Factory to create instance from builder.
 * 
 * @param id  the zone id
 * @param outputID  true if the zone id should be output
 * @param transitions  the list of Transition objects
 * @param tailZone  optional zone for getting info beyond precalculated tables
 */
static PrecalculatedZone create(String id, boolean outputID, ArrayList<Transition> transitions,
                                DSTZone tailZone) {
    int size = transitions.size();
    if (size == 0) {
        throw new IllegalArgumentException();
    }

    long[] trans = new long[size];
    int[] wallOffsets = new int[size];
    int[] standardOffsets = new int[size];
    String[] nameKeys = new String[size];

    Transition last = null;
    for (int i=0; i<size; i++) {
        Transition tr = transitions.get(i);

        if (!tr.isTransitionFrom(last)) {
            throw new IllegalArgumentException(id);
        }

        trans[i] = tr.getMillis();
        wallOffsets[i] = tr.getWallOffset();
        standardOffsets[i] = tr.getStandardOffset();
        nameKeys[i] = tr.getNameKey();

        last = tr;
    }

    // Some timezones (Australia) have the same name key for
    // summer and winter which messes everything up. Fix it here.
    String[] zoneNameData = new String[5];
    String[][] zoneStrings = new DateFormatSymbols(Locale.ENGLISH).getZoneStrings();
    for (int j = 0; j < zoneStrings.length; j++) {
        String[] set = zoneStrings[j];
        if (set != null && set.length == 5 && id.equals(set[0])) {
            zoneNameData = set;
        }
    }

    Chronology chrono = ISOChronology.getInstanceUTC();

    for (int i = 0; i < nameKeys.length - 1; i++) {
        String curNameKey = nameKeys[i];
        String nextNameKey = nameKeys[i + 1];
        long curOffset = wallOffsets[i];
        long nextOffset = wallOffsets[i + 1];
        long curStdOffset = standardOffsets[i];
        long nextStdOffset = standardOffsets[i + 1];
        Period p = new Period(trans[i], trans[i + 1], PeriodType.yearMonthDay(), chrono);
        if (curOffset != nextOffset &&
                curStdOffset == nextStdOffset &&
                curNameKey.equals(nextNameKey) &&
                p.getYears() == 0 && p.getMonths() > 4 && p.getMonths() < 8 &&
                curNameKey.equals(zoneNameData[2]) &&
                curNameKey.equals(zoneNameData[4])) {

            if (ZoneInfoCompiler.verbose()) {
                System.out.println("Fixing duplicate name key - " + nextNameKey);
                System.out.println("     - " + new DateTime(trans[i], chrono) +
                                   " - " + new DateTime(trans[i + 1], chrono));
            }
            if (curOffset > nextOffset) {
                nameKeys[i] = (curNameKey + "-Summer").intern();
            } else if (curOffset < nextOffset) {
                nameKeys[i + 1] = (nextNameKey + "-Summer").intern();
                i++;
            }
        }
    }

    if (tailZone != null) {
        if (tailZone.iStartRecurrence.getNameKey()
            .equals(tailZone.iEndRecurrence.getNameKey())) {
            if (ZoneInfoCompiler.verbose()) {
                System.out.println("Fixing duplicate recurrent name key - " +
                                   tailZone.iStartRecurrence.getNameKey());
            }
            if (tailZone.iStartRecurrence.getSaveMillis() > 0) {
                tailZone = new DSTZone(
                    tailZone.getID(),
                    tailZone.iStandardOffset,
                    tailZone.iStartRecurrence.renameAppend("-Summer"),
                    tailZone.iEndRecurrence);
            } else {
                tailZone = new DSTZone(
                    tailZone.getID(),
                    tailZone.iStandardOffset,
                    tailZone.iStartRecurrence,
                    tailZone.iEndRecurrence.renameAppend("-Summer"));
            }
        }
    }

    return new PrecalculatedZone
        ((outputID ? id : ""), trans, wallOffsets, standardOffsets, nameKeys, tailZone);
}

public long nextTransition(long instant) {
    return iZone.nextTransition(instant);
}

/**
 * Converts a local instant to a standard UTC instant with the same
 * local time. This conversion is used after performing a calculation
 * where the calculation was done using a simple local zone.
 *
 * @param instantLocal  the local instant to convert to UTC
 * @param strict  whether the conversion should reject non-existent local times
 * @return the UTC instant with the same local time, 
 * @throws ArithmeticException if the result overflows a long
 * @throws IllegalArgumentException if the zone has no equivalent local time
 * @since 1.5
 */
public long convertLocalToUTC(long instantLocal, boolean strict) {
    // get the offset at instantLocal (first estimate)
    int offsetLocal = getOffset(instantLocal);
    // adjust instantLocal using the estimate and recalc the offset
    int offset = getOffset(instantLocal - offsetLocal);
    // if the offsets differ, we must be near a DST boundary
    if (offsetLocal != offset) {
        // if strict then always check if in DST gap
        // otherwise only check if zone in Western hemisphere (as the
        // value of offset is already correct for Eastern hemisphere)
        if (strict || offsetLocal < 0) {
            // determine if we are in the DST gap
            long nextLocal = nextTransition(instantLocal - offsetLocal);
            if (nextLocal == (instantLocal - offsetLocal)) {
                nextLocal = Long.MAX_VALUE;
            }
            long nextAdjusted = nextTransition(instantLocal - offset);
            if (nextAdjusted == (instantLocal - offset)) {
                nextAdjusted = Long.MAX_VALUE;
            }
            if (nextLocal != nextAdjusted) {
                // yes we are in the DST gap
                if (strict) {
                    // DST gap is not acceptable
                    throw new IllegalArgumentException("Illegal instant due to time zone offset transition: " +
                            DateTimeFormat.forPattern("yyyy-MM-dd'T'HH:mm:ss.SSS").print(new Instant(instantLocal)) +
                            " (" + getID() + ")");
                } else {
                    // DST gap is acceptable, but for the Western hemisphere
                    // the offset is wrong and will result in local times
                    // before the cutover so use the offsetLocal instead
                    offset = offsetLocal;
                }
            }
        }
    }
    // check for overflow
    long instantUTC = instantLocal - offset;
    // If there is a sign change, but the two values have different signs...
    if ((instantLocal ^ instantUTC) < 0 && (instantLocal ^ offset) < 0) {
        throw new ArithmeticException("Subtracting time zone offset caused overflow");
    }
    return instantUTC;
}

/**
 * Decodes a built DateTimeZone from the given stream, as encoded by
 * writeTo.
 *
 * @param in input stream to read encoded DateTimeZone from.
 * @param id time zone id to assign
 */
public static DateTimeZone readFrom(DataInput in, String id) throws IOException {
    switch (in.readUnsignedByte()) {
    case 'F':
        DateTimeZone fixed = new FixedDateTimeZone
            (id, in.readUTF(), (int)readMillis(in), (int)readMillis(in));
        if (fixed.equals(DateTimeZone.UTC)) {
            fixed = DateTimeZone.UTC;
        }
        return fixed;
    case 'C':
        return CachedDateTimeZone.forZone(PrecalculatedZone.readFrom(in, id));
    case 'P':
        return PrecalculatedZone.readFrom(in, id);
    default:
        throw new IOException("Invalid encoding");
    }
}

private static int parseOffset(String str) {
    // Can't use a real chronology if called during class
    // initialization. Offset parser doesn't need it anyhow.
    Chronology chrono = new BaseChronology() {
        public DateTimeZone getZone() {
            return null;
        }
        public Chronology withUTC() {
            return this;
        }
        public Chronology withZone(DateTimeZone zone) {
            return this;
        }
        public String toString() {
            return getClass().getName();
        }
    };
    return -(int) offsetFormatter().withChronology(chrono).parseMillis(str);
}

/**
 * Output the date time in ISO8601 format (yyyy-MM-ddTHH:mm:ss.SSSZZ).
 * 
 * @return ISO8601 time formatted string.
 */
@ToString
public String toString() {
    return ISODateTimeFormat.dateTime().print(this);
}

/**
 * Processes all the rules and builds a DateTimeZone.
 *
 * @param id  time zone id to assign
 * @param outputID  true if the zone id should be output
 */
public DateTimeZone toDateTimeZone(String id, boolean outputID) {
    if (id == null) {
        throw new IllegalArgumentException();
    }

    // Discover where all the transitions occur and store the results in
    // these lists.
    ArrayList<Transition> transitions = new ArrayList<Transition>();

    // Tail zone picks up remaining transitions in the form of an endless
    // DST cycle.
    DSTZone tailZone = null;

    long millis = Long.MIN_VALUE;
    int saveMillis = 0;

    int ruleSetCount = iRuleSets.size();
    for (int i=0; i<ruleSetCount; i++) {
        RuleSet rs = iRuleSets.get(i);
        Transition next = rs.firstTransition(millis);
        if (next == null) {
            continue;
        }
        addTransition(transitions, next);
        millis = next.getMillis();
        saveMillis = next.getSaveMillis();

        // Copy it since we're going to destroy it.
        rs = new RuleSet(rs);

        while ((next = rs.nextTransition(millis, saveMillis)) != null) {
            if (addTransition(transitions, next)) {
                if (tailZone != null) {
                    // Got the extra transition before DSTZone.
                    break;
                }
            }
            millis = next.getMillis();
            saveMillis = next.getSaveMillis();
            if (tailZone == null && i == ruleSetCount - 1) {
                tailZone = rs.buildTailZone(id);
                // If tailZone is not null, don't break out of main loop until
                // at least one more transition is calculated. This ensures a
                // correct 'seam' to the DSTZone.
            }
        }

        millis = rs.getUpperLimit(saveMillis);
    }

    // Check if a simpler zone implementation can be returned.
    if (transitions.size() == 0) {
        if (tailZone != null) {
            // This shouldn't happen, but handle just in case.
            return tailZone;
        }
        return buildFixedZone(id, "UTC", 0, 0);
    }
    if (transitions.size() == 1 && tailZone == null) {
        Transition tr = transitions.get(0);
        return buildFixedZone(id, tr.getNameKey(),
                              tr.getWallOffset(), tr.getStandardOffset());
    }

    PrecalculatedZone zone = PrecalculatedZone.create(id, outputID, transitions, tailZone);
    if (zone.isCachable()) {
        return CachedDateTimeZone.forZone(zone);
    }
    return zone;
}

/**
 * Gets the default zone provider.
 * <p>
 * Tries the system property <code>org.joda.time.DateTimeZone.Provider</code>.
 * Then tries a <code>ZoneInfoProvider</code> using the data in <code>org/joda/time/tz/data</code>.
 * Then uses <code>UTCProvider</code>.
 * 
 * @return the default name provider
 */
private static Provider getDefaultProvider() {
    Provider provider = null;

    try {
        String providerClass =
            System.getProperty("org.joda.time.DateTimeZone.Provider");
        if (providerClass != null) {
            try {
                provider = (Provider) Class.forName(providerClass).newInstance();
            } catch (Exception ex) {
                Thread thread = Thread.currentThread();
                thread.getThreadGroup().uncaughtException(thread, ex);
            }
        }
    } catch (SecurityException ex) {
        // ignored
    }

    if (provider == null) {
        try {
            provider = new ZoneInfoProvider("org/joda/time/tz/data");
        } catch (Exception ex) {
            Thread thread = Thread.currentThread();
            thread.getThreadGroup().uncaughtException(thread, ex);
        }
    }

    if (provider == null) {
        provider = new UTCProvider();
    }

    return provider;
}

/**
 * Parses only the local date-time from the given text, returning a new LocalDate.
 * <p>
 * This will parse the text fully according to the formatter, using the UTC zone.
 * Once parsed, only the local date-time will be used.
 * This means that any parsed time-zone or offset field is completely ignored.
 * It also means that the zone and offset-parsed settings are ignored.
 *
 * @param text  the text to parse, not null
 * @return the parsed date-time, never null
 * @throws UnsupportedOperationException if parsing is not supported
 * @throws IllegalArgumentException if the text to parse is invalid
 * @since 2.0
 */
public LocalDateTime parseLocalDateTime(String text) {
    DateTimeParser parser = requireParser();

    Chronology chrono = selectChronology(null).withUTC();  // always use UTC, avoiding DST gaps
    DateTimeParserBucket bucket = new DateTimeParserBucket(0, chrono, iLocale, iPivotYear, iDefaultYear);
    int newPos = parser.parseInto(bucket, text, 0);
    if (newPos >= 0) {
        if (newPos >= text.length()) {
            long millis = bucket.computeMillis(true, text);
            if (bucket.getZone() == null) {  // treat withOffsetParsed() as being true
                int parsedOffset = bucket.getOffset();
                DateTimeZone parsedZone = DateTimeZone.forOffsetMillis(parsedOffset);
                chrono = chrono.withZone(parsedZone);
            }
            return new LocalDateTime(millis, chrono);
        }
    } else {
        newPos = ~newPos;
    }
    throw new IllegalArgumentException(FormatUtils.createErrorMessage(text, newPos));
}

/**
 * Gets a time zone instance for the specified time zone id.
 * <p>
 * The time zone id may be one of those returned by getAvailableIDs.
 * Short ids, as accepted by {@link java.util.TimeZone}, are not accepted.
 * All IDs must be specified in the long format.
 * The exception is UTC, which is an acceptable id.
 * <p>
 * Alternatively a locale independent, fixed offset, datetime zone can
 * be specified. The form <code>[+-]hh:mm</code> can be used.
 * 
 * @param id  the ID of the datetime zone, null means default
 * @return the DateTimeZone object for the ID
 * @throws IllegalArgumentException if the ID is not recognised
 */
@FromString
public static DateTimeZone forID(String id) {
    if (id == null) {
        return getDefault();
    }
    if (id.equals("UTC")) {
        return DateTimeZone.UTC;
    }
    DateTimeZone zone = cProvider.getZone(id);
    if (zone != null) {
        return zone;
    }
    if (id.startsWith("+") || id.startsWith("-")) {
        int offset = parseOffset(id);
        if (offset == 0L) {
            return DateTimeZone.UTC;
        } else {
            id = printOffset(offset);
            return fixedOffsetZone(id, offset);
        }
    }
    throw new IllegalArgumentException("The datetime zone id '" + id + "' is not recognised");
}

/**
 * Returns a formatter that combines a full date and time, separated by a 'T'
 * (yyyy-MM-dd'T'HH:mm:ss.SSSZZ).
 * The time zone offset is 'Z' for zero, and of the form '\u00b1HH:mm' for non-zero.
 * 
 * @return a formatter for yyyy-MM-dd'T'HH:mm:ss.SSSZZ
 */
public static DateTimeFormatter dateTime() {
    if (dt == null) {
        dt = new DateTimeFormatterBuilder()
            .append(date())
            .append(tTime())
            .toFormatter();
    }
    return dt;
}

private Info createInfo(long millis) {
    long periodStart = millis & (0xffffffffL << 32);
    Info info = new Info(iZone, periodStart);

    long end = periodStart | 0xffffffffL;
    Info chain = info;
    while (true) {
        long next = iZone.nextTransition(periodStart);
        if (next == periodStart || next > end) {
            break;
        }
        periodStart = next;
        chain = (chain.iNextInfo = new Info(iZone, periodStart));
    }

    return info;
}

/**
 * Returns a formatter for a two digit hour of day, two digit minute of
 * hour, two digit second of minute, three digit fraction of second, and
 * time zone offset prefixed by 'T' ('T'HH:mm:ss.SSSZZ).
 * The time zone offset is 'Z' for zero, and of the form '\u00b1HH:mm' for non-zero.
 * 
 * @return a formatter for 'T'HH:mm:ss.SSSZZ
 */
public static DateTimeFormatter tTime() {
    if (tt == null) {
        tt = new DateTimeFormatterBuilder()
            .append(literalTElement())
            .append(time())
            .toFormatter();
    }
    return tt;
}

/**
 * Gets the millisecond offset to subtract from local time to get UTC time.
 * This offset can be used to undo adding the offset obtained by getOffset.
 *
 * <pre>
 * millisLocal == millisUTC   + getOffset(millisUTC)
 * millisUTC   == millisLocal - getOffsetFromLocal(millisLocal)
 * </pre>
 *
 * NOTE: After calculating millisLocal, some error may be introduced. At
 * offset transitions (due to DST or other historical changes), ranges of
 * local times may map to different UTC times.
 * <p>
 * This method will return an offset suitable for calculating an instant
 * after any DST gap. For example, consider a zone with a cutover
 * from 01:00 to 01:59:<br />
 * Input: 00:00  Output: 00:00<br />
 * Input: 00:30  Output: 00:30<br />
 * Input: 01:00  Output: 02:00<br />
 * Input: 01:30  Output: 02:30<br />
 * Input: 02:00  Output: 02:00<br />
 * Input: 02:30  Output: 02:30<br />
 * <p>
 * During a DST overlap (where the local time is ambiguous) this method will return
 * the earlier instant. The combination of these two rules is to always favour
 * daylight (summer) time over standard (winter) time.
 * <p>
 * NOTE: Prior to v2.0, the DST overlap behaviour was not defined and varied by hemisphere.
 * Prior to v1.5, the DST gap behaviour was also not defined.
 *
 * @param instantLocal  the millisecond instant, relative to this time zone, to get the offset for
 * @return the millisecond offset to subtract from local time to get UTC time
 */
public int getOffsetFromLocal(long instantLocal) {
    // get the offset at instantLocal (first estimate)
    final int offsetLocal = getOffset(instantLocal);
    // adjust instantLocal using the estimate and recalc the offset
    final long instantAdjusted = instantLocal - offsetLocal;
    final int offsetAdjusted = getOffset(instantAdjusted);
    // if the offsets differ, we must be near a DST boundary
    if (offsetLocal != offsetAdjusted) {
        // we need to ensure that time is always after the DST gap
        // this happens naturally for positive offsets, but not for negative
        if ((offsetLocal - offsetAdjusted) < 0) {
            // if we just return offsetAdjusted then the time is pushed
            // back before the transition, whereas it should be
            // on or after the transition
            long nextLocal = nextTransition(instantAdjusted);
            long nextAdjusted = nextTransition(instantLocal - offsetAdjusted);
            if (nextLocal != nextAdjusted) {
                return offsetLocal;
            }
        }
    }
    return offsetAdjusted;
}

/**
 * Returns a formatter for a two digit hour of day, two digit minute of
 * hour, two digit second of minute, three digit fraction of second, and
 * time zone offset (HH:mm:ss.SSSZZ).
 * The time zone offset is 'Z' for zero, and of the form '\u00b1HH:mm' for non-zero.
 * 
 * @return a formatter for HH:mm:ss.SSSZZ
 */
public static DateTimeFormatter time() {
    if (t == null) {
        t = new DateTimeFormatterBuilder()
            .append(hourMinuteSecondFraction())
            .append(offsetElement())
            .toFormatter();
    }
    return t;
}

